begin;
select plan(49);

select has_type('public', 'appointment_status', 'appointment status exists');
select enum_has_labels('public', 'appointment_status', array['CONFIRMED'], 'appointment status is minimal for this slice');
select ok('CONFIRMED' = any(enum_range(null::public.booking_offer_status)::text[]), 'offer has confirmed state');
select ok('CONFIRMED' = any(enum_range(null::public.booking_option_status)::text[]), 'option has confirmed state');
select has_table('public', 'appointment', 'appointment table exists');
select has_table('public', 'appointment_google_event', 'Google synchronization relation exists');
select ok((select relrowsecurity from pg_class where oid = 'public.appointment'::regclass), 'appointment RLS enabled');
select ok((select relrowsecurity from pg_class where oid = 'public.appointment_google_event'::regclass), 'Google synchronization RLS enabled');
select ok(not has_table_privilege('anon', 'public.appointment', 'select'), 'anonymous users cannot read appointments');
select ok(not has_table_privilege('service_role', 'public.appointment', 'select'), 'service role uses guarded appointment RPCs');
select ok(not has_table_privilege('anon', 'public.appointment_google_event', 'select'), 'anonymous users cannot read event identities');
select ok(not has_table_privilege('service_role', 'public.appointment_google_event', 'select'), 'service role uses guarded event RPCs');
select has_function('public', 'get_public_booking_confirmation_context', array['text','timestamp with time zone'], 'confirmation context RPC exists');
select has_function('public', 'finalize_public_booking_confirmation', array['text','uuid','text','text','text','timestamp with time zone'], 'atomic finalization RPC exists');
select has_function('public', 'mark_booking_confirmation_reauth_required', array['uuid','uuid'], 'reauth transition RPC exists');
select ok(has_function_privilege('service_role', 'public.get_public_booking_confirmation_context(text,timestamptz)', 'execute'), 'service role can coordinate confirmation');
select ok(has_function_privilege('service_role', 'public.finalize_public_booking_confirmation(text,uuid,text,text,text,timestamptz)', 'execute'), 'service role can finalize confirmation');
select ok(has_function_privilege('service_role', 'public.mark_booking_confirmation_reauth_required(uuid,uuid)', 'execute'), 'service role can mark reauth');
select ok(not has_function_privilege('anon', 'public.get_public_booking_confirmation_context(text,timestamptz)', 'execute'), 'anonymous browser cannot call context RPC');
select ok(not has_function_privilege('authenticated', 'public.finalize_public_booking_confirmation(text,uuid,text,text,text,timestamptz)', 'execute'), 'authenticated browser cannot finalize directly');
select is((select proconfig from pg_proc where oid = 'public.finalize_public_booking_confirmation(text,uuid,text,text,text,timestamptz)'::regprocedure), array['search_path=""'], 'finalization fixes an empty search path');
select ok((select prosrc ilike '%for update of offer%' from pg_proc where oid = 'public.finalize_public_booking_confirmation(text,uuid,text,text,text,timestamptz)'::regprocedure), 'finalization serializes concurrent attempts on the offer');
select is((select count(*) from pg_constraint where conrelid = 'public.appointment'::regclass and contype = 'u' and pg_get_constraintdef(oid) ilike '%booking_offer_id%'), 1::bigint, 'one appointment is allowed per offer');
select is((select count(*) from pg_constraint where conrelid = 'public.appointment_google_event'::regclass and contype = 'u' and pg_get_constraintdef(oid) ilike '%calendar_id%event_id%'), 1::bigint, 'provider event identity is unique per calendar');

set local role service_role;
select lives_ok($setup$
  insert into public.customer(id, studio_id, name, status) values ('60000000-0000-0000-0000-000000000040', '20000000-0000-0000-0000-000000000001', 'Confirmation client', 'ACTIVE');
  insert into public.tattoo_case(id, studio_id, customer_id, summary, artist_profile_id, status) values ('70000000-0000-0000-0000-000000000040', '20000000-0000-0000-0000-000000000001', '60000000-0000-0000-0000-000000000040', 'Private confirmation case', '50000000-0000-0000-0000-000000000001', 'OPEN');
  select public.activate_google_calendar_connection('20000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 'v1.confirmation-ciphertext.tag', array['https://www.googleapis.com/auth/calendar.calendarlist.readonly','https://www.googleapis.com/auth/calendar.events.freebusy','https://www.googleapis.com/auth/calendar.events']);
  select public.assign_artist_calendar('20000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000001', 'artist@example.test');
  create temporary table confirmation_connection as select id from public.get_google_calendar_connection('20000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001');
  create temporary table confirmation_offer as select (public.create_booking_offer('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000040','50000000-0000-0000-0000-000000000001','[{"startUtc":"2026-09-20T09:00:00.000Z","endUtc":"2026-09-20T10:00:00.000Z"}]','2026-09-15T10:00:00Z')->>'id')::uuid offer_id;
  select public.rotate_booking_offer_public_access('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',(select offer_id from confirmation_offer),repeat('56',32),'2026-09-15T10:01:00Z');
  create temporary table confirmation_selector as select public.get_public_booking_offer(repeat('56',32),'2026-09-15T10:02:00Z')->'options'->0->>'selector' selector;
  select public.select_public_booking_offer(repeat('56',32),(select selector from confirmation_selector),'2026-09-15T10:03:00Z');
$setup$, 'synthetic selected offer has an assigned fully-scoped calendar');
select is(public.get_public_booking_confirmation_context(repeat('56',32),'2026-09-15T10:04:00Z')->>'state', 'PENDING', 'context exposes pending state');
select ok((public.get_public_booking_confirmation_context(repeat('56',32),'2026-09-15T10:04:00Z')->>'option_id') ~ '^[0-9a-f-]{36}$', 'context identifies the selected internal option');
select is(public.get_public_booking_confirmation_context(repeat('56',32),'2026-09-15T10:04:00Z')->>'start_at', '2026-09-20T09:00:00+00:00', 'context preserves the exact selected start');
select ok((public.get_public_booking_confirmation_context(repeat('56',32),'2026-09-15T10:04:00Z')->'connection'->'granted_scopes') @> '["https://www.googleapis.com/auth/calendar.events"]'::jsonb, 'context exposes the incremental event grant internally');
select ok(not public.get_public_booking_confirmation_context(repeat('56',32),'2026-09-15T10:04:00Z') ?| array['customer','tattoo_case','summary'], 'confirmation context omits unrelated customer and case data');
select is(public.finalize_public_booking_confirmation(repeat('56',32),(select id from confirmation_connection),'artist@example.test','inkendar0123456789abc',repeat('C',43),'2026-09-15T10:05:00Z')->>'confirmed_at', '2026-09-15T10:05:00+00:00', 'finalization returns the persisted confirmation time');
reset role;
select is((select status::text from public.booking_offer where id = (select offer_id from confirmation_offer)), 'CONFIRMED', 'offer becomes confirmed atomically');
select is((select status::text from public.booking_option where offer_id = (select offer_id from confirmation_offer)), 'CONFIRMED', 'selected option becomes confirmed atomically');
select is((select count(*) from public.appointment where booking_offer_id = (select offer_id from confirmation_offer)), 1::bigint, 'one appointment is created');
select is((select count(*) from public.appointment_google_event event join public.appointment appointment on appointment.id = event.appointment_id where appointment.booking_offer_id = (select offer_id from confirmation_offer)), 1::bigint, 'one minimal Google sync relation is created');
set local role service_role;
select is(public.finalize_public_booking_confirmation(repeat('56',32),(select id from confirmation_connection),'artist@example.test','inkendar0123456789abc',repeat('C',43),'2026-09-15T10:06:00Z')->>'confirmed_at', '2026-09-15T10:05:00+00:00', 'serialized retry converges on the original confirmation');
reset role;
select is((select count(*) from public.appointment where booking_offer_id = (select offer_id from confirmation_offer)), 1::bigint, 'idempotent retry creates no duplicate');
set local role service_role;
select throws_ok($$select public.finalize_public_booking_confirmation(repeat('56',32),(select id from confirmation_connection),'artist@example.test','inkendar0123456789abd',repeat('C',43),'2026-09-15T10:07:00Z')$$, 'P0003', null, 'mismatched provider identity fails closed');
select is(public.get_public_booking_offer(repeat('56',32),'2026-09-17T10:00:00Z')->>'state', 'CONFIRMED', 'confirmed public view survives original expiry');
select ok(not public.get_public_booking_offer(repeat('56',32),'2026-09-17T10:00:00Z') ?| array['event_id','calendar_id','correlation','connection'], 'public confirmed view omits provider identity');
select is(public.expire_booking_offers('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','2026-09-17T10:00:00Z'), 0, 'expiry does not alter confirmed offers');
reset role;
select is((select status::text from public.booking_offer where id = (select offer_id from confirmation_offer)), 'CONFIRMED', 'confirmed state remains after expiry processing');
set local role service_role;
select is((select count(*) from public.list_active_booking_holds('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','2026-09-20T00:00:00Z','2026-09-21T00:00:00Z','2026-09-17T10:00:00Z')), 1::bigint, 'confirmed appointment remains an availability exclusion after offer expiry');
select throws_ok($$select public.create_booking_offer('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000040','50000000-0000-0000-0000-000000000001','[{"startUtc":"2026-09-20T09:30:00.000Z","endUtc":"2026-09-20T10:30:00.000Z"}]','2026-09-17T10:00:00Z')$$, '23P01', null, 'new holds cannot overlap confirmed appointments');
select lives_ok($$select public.create_booking_offer('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000040','50000000-0000-0000-0000-000000000001','[{"startUtc":"2026-09-20T10:00:00.000Z","endUtc":"2026-09-20T11:00:00.000Z"}]','2026-09-17T10:00:00Z')$$, 'adjacent end-exclusive interval remains available');
select lives_ok(format('select public.mark_booking_confirmation_reauth_required(%L,%L)', '20000000-0000-0000-0000-000000000001', (select id from confirmation_connection)), 'invalid grant marks only the bound connection');
select is((select status::text from public.get_google_calendar_connection('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001')), 'REAUTH_REQUIRED', 'confirmation connection requires reauthorization');
select is((select count(*) from public.list_artist_calendar_assignments('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001') where calendar_id = 'artist@example.test'), 1::bigint, 'reauth preserves the selected calendar assignment');
select is(public.get_public_booking_offer(repeat('56',32),'2026-09-17T10:00:00Z')->>'state', 'CONFIRMED', 'reauth does not downgrade a confirmed public view');

select * from finish();
rollback;
